 s=s.replace("data.value=result.points.map(p=>p.height+'\\t'+p.volume).join('\\n');", "data.value=draft.value?.kind==='Decimal'?(result.decimalRows||[]).map(r=>[r.startHeightMm,r.endHeightMm,r.number,r.centimetreLitres,r.millimetreLitres].join('\\t')).join('\\n'):result.points.map(p=>p.height+'\\t'+p.volume).join('\\n');")
 s=s.replace('@change="checked=false"><option v-for="(name,key) in kinds"','@change="kindChanged"><option v-for="(name,key) in kinds"')
 s=s.replace('v-model="draft.heightUnit" :disabled="!admin"','v-model="draft.heightUnit" :disabled="!admin||draft.kind===\'Decimal\'"').replace('v-model="draft.volumeUnit" :disabled="!admin"','v-model="draft.volumeUnit" :disabled="!admin||draft.kind===\'Decimal\'"')
 s=s.replace('<p class="capacity-import-help">按模板填写：','<p v-if="draft.kind===\'Decimal\'" class="capacity-import-help">小数表按五列模板填写：起始高度mm、结束高度mm、序号1～9、厘米累计增量L、毫米累计增量L。每区段9行，起止高度每行重复，第2行起填数据。</p><p v-else class="capacity-import-help">按模板填写：')
 s=s.replace('<details class="capacity-import-example">','<details v-if="draft.kind!==\'Decimal\'" class="capacity-import-example">')
 s=s.replace('<details><summary>其他格式设置','<details v-if="draft.kind!==\'Decimal\'"><summary>其他格式设置')
 s=s.replace("{{draft.kind==='StaticPressure'?'液位高度、参考密度下的容积修正量（不是总容积）':'液位高度、容积'}}（每行两列）", "{{draft.kind==='Decimal'?'起始mm、结束mm、序号、厘米增量L、毫米增量L（每行五列）':draft.kind==='StaticPressure'?'液位高度、参考密度下的容积修正量（每行两列）':'液位高度、容积（每行两列）'}}")
 s=s.replace('小数表组合算法尚未确认，本版可维护和关联，暂不参与体积计算。','小数表仅在储罐选择“主表下节点＋小数表增量”时参与。高度用mm、增量用L；旧两列表须按新格式重新校核。')
 s=s.replace('{{draft.points.length}}组 · 首行',"{{draft.kind==='Decimal'?(draft.decimalRows?.length||0):draft.points.length}}组 · 首行")
 return s
